        '                        .frame(width: 52, height: 52)',
        '                        .overlay(RoundedRectangle(cornerRadius: 14)',
        '                            .stroke(inPlan ? theme.accent.opacity(0.5) : Color.white.opacity(0.08), lineWidth: 1))',
        '                    Image(systemName: instance.icon)',
