        '                    .transition(.asymmetric(',
        '                        insertion: .move(edge: .top).combined(with: .opacity),',
        '                        removal: .opacity',
        '                    ))',
        '            }',
        '        }',
        '        .background(isExpanded && inPlan ? theme.accent.opacity(0.06) : Color.clear)',
        '        .clipShape(RoundedRectangle(cornerRadius: 16, style: .continuous))',
